// Generates the three image assets that Inno Setup needs:
//   installer-icon.ico   — 16/32/48/64/128/256 multi-size ICO (PNG-embedded)
//   installer-banner.bmp — 164x314 left-side wizard image (BMP)
//   installer-small.bmp  — 55x58 corner wizard image (BMP)
//
// All three are derived from apps/bridge/assets/icon.png, which is itself
// generated by apps/bridge/assets/generate-icons.cjs. So the typical flow is:
//
//   pnpm --filter bridge install      # ensures sharp is available
//   node apps/bridge/assets/generate-icons.cjs
//   node apps/bridge/installer/assets/generate-installer-assets.cjs

const path = require("node:path");
const fs = require("node:fs");

(async () => {
  let sharp;
  try {
    sharp = require("sharp");
  } catch (err) {
    console.error("[installer-assets] sharp not installed.");
    console.error("Run `pnpm install` from the repo root first, then re-run this script.");
    process.exit(1);
  }

  const outDir = __dirname;
  const baseIcon = path.resolve(__dirname, "..", "..", "assets", "icon.png");

  if (!fs.existsSync(baseIcon)) {
    console.error("[installer-assets] base icon missing: " + baseIcon);
    console.error("Run `node apps/bridge/assets/generate-icons.cjs` first.");
    process.exit(1);
  }

  // Brand background — Mote yellow-ish for visibility against the wizard chrome.
  const bg = { r: 254, g: 249, b: 195 };

  // ---- ICO (multi-size, PNG-embedded; supported on Vista and newer) -------
  const sizes = [16, 32, 48, 64, 128, 256];
  const pngBuffers = await Promise.all(
    sizes.map((s) =>
      sharp(baseIcon)
        .resize(s, s, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } })
        .png()
        .toBuffer()
    )
  );

  const headerSize = 6 + 16 * sizes.length;
  const totalSize = headerSize + pngBuffers.reduce((a, b) => a + b.length, 0);
  const ico = Buffer.alloc(totalSize);

  ico.writeUInt16LE(0, 0);              // reserved
  ico.writeUInt16LE(1, 2);              // type 1 = icon
  ico.writeUInt16LE(sizes.length, 4);   // image count

  let dataOffset = headerSize;
  for (let i = 0; i < sizes.length; i++) {
    const s = sizes[i];
    const buf = pngBuffers[i];
    const entry = 6 + i * 16;
    ico.writeUInt8(s === 256 ? 0 : s, entry + 0);  // width  (0 = 256)
    ico.writeUInt8(s === 256 ? 0 : s, entry + 1);  // height (0 = 256)
    ico.writeUInt8(0, entry + 2);                  // palette colors
    ico.writeUInt8(0, entry + 3);                  // reserved
    ico.writeUInt16LE(1, entry + 4);               // color planes
    ico.writeUInt16LE(32, entry + 6);              // bits per pixel
    ico.writeUInt32LE(buf.length, entry + 8);      // image data size
    ico.writeUInt32LE(dataOffset, entry + 12);     // image data offset
    buf.copy(ico, dataOffset);
    dataOffset += buf.length;
  }

  const icoPath = path.join(outDir, "installer-icon.ico");
  fs.writeFileSync(icoPath, ico);
  console.log("[installer-assets] wrote", icoPath, ico.length, "bytes (" + sizes.length + " sizes)");

  // ---- Wizard images (BMP, 24-bit; Inno Setup is picky about format) ------
  // sharp doesn't write BMP, so we render raw RGB then wrap in a BMP header
  // ourselves. Inno Setup wants Windows BMP3 (BITMAPINFOHEADER, 24bpp, BGR,
  // bottom-up rows padded to 4-byte boundaries).
  async function writeBmp24(targetPath, width, height, sharpPipeline) {
    const { data } = await sharpPipeline
      .resize(width, height, { fit: "cover", background: bg })
      .flatten({ background: bg })
      .removeAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });

    const rowSize = Math.floor((24 * width + 31) / 32) * 4; // 4-byte aligned
    const pixelArraySize = rowSize * height;
    const fileSize = 14 + 40 + pixelArraySize;
    const buf = Buffer.alloc(fileSize);

    // BITMAPFILEHEADER
    buf.write("BM", 0, "ascii");
    buf.writeUInt32LE(fileSize, 2);
    buf.writeUInt16LE(0, 6);
    buf.writeUInt16LE(0, 8);
    buf.writeUInt32LE(54, 10);

    // BITMAPINFOHEADER
    buf.writeUInt32LE(40, 14);
    buf.writeInt32LE(width, 18);
    buf.writeInt32LE(height, 22);
    buf.writeUInt16LE(1, 26);
    buf.writeUInt16LE(24, 28);
    buf.writeUInt32LE(0, 30);             // BI_RGB
    buf.writeUInt32LE(pixelArraySize, 34);
    buf.writeInt32LE(2835, 38);
    buf.writeInt32LE(2835, 42);
    buf.writeUInt32LE(0, 46);
    buf.writeUInt32LE(0, 50);

    // Pixel data (bottom-up, BGR, padded rows)
    let pos = 54;
    for (let y = height - 1; y >= 0; y--) {
      const rowStart = y * width * 3;
      for (let x = 0; x < width; x++) {
        const rgb = rowStart + x * 3;
        buf[pos++] = data[rgb + 2]; // B
        buf[pos++] = data[rgb + 1]; // G
        buf[pos++] = data[rgb + 0]; // R
      }
      const padding = rowSize - width * 3;
      for (let p = 0; p < padding; p++) buf[pos++] = 0;
    }

    fs.writeFileSync(targetPath, buf);
  }

  // 164x314 left-side wizard image
  await writeBmp24(
    path.join(outDir, "installer-banner.bmp"),
    164, 314,
    sharp({
      create: { width: 164, height: 314, channels: 3, background: bg },
    }).composite([
      {
        input: await sharp(baseIcon)
          .resize(120, 120, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } })
          .png()
          .toBuffer(),
        top: 80,
        left: 22,
      },
    ])
  );
  console.log("[installer-assets] wrote installer-banner.bmp (164x314)");

  // 55x58 corner wizard image
  await writeBmp24(
    path.join(outDir, "installer-small.bmp"),
    55, 58,
    sharp({
      create: { width: 55, height: 58, channels: 3, background: bg },
    }).composite([
      {
        input: await sharp(baseIcon)
          .resize(48, 48, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } })
          .png()
          .toBuffer(),
        top: 5,
        left: 3,
      },
    ])
  );
  console.log("[installer-assets] wrote installer-small.bmp (55x58)");

  console.log("[installer-assets] done");
})().catch((err) => {
  console.error("[installer-assets] failed", err);
  process.exit(1);
});
